text:
{
 "lead": {
  "es": "子《こ》どもが多《おお》く、教育《きょういく》にかかるお金《かね》（教育費《きょういくひ》）をたくさんはらっている家《いえ》があります。その家《いえ》の負担《ふたん》を軽《かる》くするための法律《ほうりつ》です。その家《いえ》の学生《がくせい》などの、大学《だいがく》などの授業料《じゅぎょうりょう》などをへらしたり、なくしたりするしくみ（減免制度《げんめんせいど》）をつくることなどをします。",
  "hs": "多くの子どもなどの教育費を負担している家庭の負担を軽くするため、その家庭の学生などの大学などの授業料等を減らしたり免除《めんじょ》したりする制度（減免制度《げんめんせいど》）をつくるなどの法律です。"
 },
 "facts/0/text": {
  "es": "法律《ほうりつ》の目的《もくてき》を、つぎのように変《か》えます。子《こ》どもが多《おお》く、教育費《きょういくひ》をたくさんはらっている家《いえ》があります。お金《かね》のりゆうで、教育費《きょういくひ》をはらうのがとてもむずかしい家《いえ》もあります。こうした家《いえ》の負担《ふたん》の一部《いちぶ》を、社会《しゃかい》全体《ぜんたい》で受《う》けもって軽《かる》くします。そのために、こうした家《いえ》の学生《がくせい》などの、大学《だいがく》などの授業料《じゅぎょうりょう》などをへらしたり、なくしたりします。そして、子育《こそだ》てに希望《きぼう》をもてる社会《しゃかい》をつくることに役立《やくだ》てます。",
  "hs": "法律の目的を、多くの子どもなどの教育費を負担している家庭と、経済的な理由で教育費の負担を求めることが極めて難しい家庭の負担の一部を社会全体で負担して軽くするため、これらの家庭の学生などの大学などの授業料等を減免《げんめん》し、子育てに希望を持つことができる社会の実現に役立つことに改めます。"
 },
 "facts/1/text": {
  "es": "授業料《じゅぎょうりょう》などをへらしたり、なくしたりしてもらえる人《ひと》に、子《こ》どもが多《おお》く教育費《きょういくひ》をたくさんはらっている家《いえ》の学生《がくせい》などをくわえます。※正《ただ》しくは、「3人《にん》以上《いじょう》の子《こ》どもなどのくらしをささえている人《ひと》に、くらしをささえてもらっている子《こ》どもである学生《がくせい》など」です。",
  "hs": "授業料等の減免《げんめん》の対象者に、多くの子どもなどの教育費を負担している家庭の学生など（3人以上の子どもなどの生計を維持《いじ》する人に生計を維持《いじ》されている子どもなどである学生など）を加えます。"
 },
 "facts/2/text": {
  "es": "授業料《じゅぎょうりょう》などをへらしてもらいたい学生《がくせい》などは、もうしこみの紙《かみ》（申請書《しんせいしょ》）などを出《だ》します。紙《かみ》には、あてはまるりゆう（認定《にんてい》事由《じゆう》）などを書《か》きます。出《だ》す先《さき》は、文部科学大臣《もんぶかがくだいじん》などから「一定《いってい》の条件《じょうけん》にあっている」とみとめられた大学《だいがく》など（確認《かくにん》大学《だいがく》等《とう》）をつくった人《ひと》です。その人《ひと》が、文部科学省《もんぶかがくしょう》のきまりの基準《きじゅん》とやり方《かた》で、みとめるかどうかを決《き》めます。べつのりゆうでへらしてもらうときは、あらためてみとめてもらわなければなりません（変更《へんこう》認定《にんてい》）。",
  "hs": "授業料等の減免《げんめん》の認定を受けようとする学生などは、あてはまる認定事由などを書いた申請書《しんせいしょ》などを、文部科学大臣などから一定の要件を満たすと確認を受けた大学など（確認大学等）の設置者に出し、設置者は文部科学省令で定める基準と方法で認定します。別の認定事由で減免《げんめん》を受けるときは、変更《へんこう》認定を受けなければなりません。"
 },
 "facts/3/text": {
  "es": "学生《がくせい》などと、そのくらしをささえている人《ひと》の収入《しゅうにゅう》を見《み》て、授業料《じゅぎょうりょう》などをはらうのがとてもむずかしい人《ひと》がいます。こうした人《ひと》の授業料《じゅぎょうりょう》などをへらすことについて、国《くに》は気《き》をくばります。日本《にほん》学生支援《がくせいしえん》機構《きこう》の法律《ほうりつ》による、学《まな》ぶためのお金《かね》をわたすこと（学資《がくし》の支給《しきゅう》）とあわせて、大学《だいがく》などで学《まな》ぶためのいろいろなお金《かね》をまとめてささえられるようにします。",
  "hs": "国は、学生などとその生計を維持《いじ》する人の収入の状況《じょうきょう》から、授業料等の負担を求めることが極めて難しい人の減免《げんめん》について、独立行政法人日本｜学生支援《がくせいしえん》機構法の学資の支給（学ぶためのお金の支給）と合わせて、大学などで学ぶための諸費用への総合的な支援《しえん》となるよう配慮《はいりょ》します。"
 },
 "facts/4/text": {
  "es": "政府《せいふ》は、この法律《ほうりつ》が使《つか》われはじめてから4年《ねん》をめやすに、新《あたら》しい法律《ほうりつ》がどう使《つか》われているかを調《しら》べます。必要《ひつよう》があるとみとめたときは、必要《ひつよう》な対応《たいおう》をします。",
  "hs": "政府は、施行後《しこうご》4年をめどに新しい法律の施行《しこう》の状況《じょうきょう》を検討し、必要があると認めるときは必要な措置《そち》（対応）をとります。"
 },
 "facts/5/text": {
  "es": "この法律《ほうりつ》は、一部《いちぶ》をのぞき、令和《れいわ》7年《ねん》4月《がつ》1日《ついたち》から使《つか》われます。",
  "hs": "この法律は、一部を除き、令和7年4月1日から施行《しこう》されます（使われ始めます）。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、つぎのように説明《せつめい》しています。子《こ》どもが多《おお》く、教育費《きょういくひ》をたくさんはらっている家《いえ》の負担《ふたん》を軽《かる》くする必要《ひつよう》があります。そのために、その家《いえ》の学生《がくせい》などの、大学《だいがく》などの授業料《じゅぎょうりょう》などをへらしたり、なくしたりするしくみをつくることなどをする必要《ひつよう》があるためです。",
  "hs": "内閣は、多くの子どもなどの教育費を負担している家庭の教育費の負担を軽くするため、その家庭の学生などの大学などの授業料等の減免制度《げんめんせいど》を創設するなどの措置《そち》をとる必要があるためとしている。"
 },
 "more/who/text": {
  "es": "3人《にん》以上《いじょう》の子《こ》どもなどのくらしをささえている人《ひと》に、くらしをささえてもらっている学生《がくせい》など（子《こ》どもが多《おお》い家《いえ》の学生《がくせい》など。収入《しゅうにゅう》の多《おお》さの制限《せいげん》はありません）。収入《しゅうにゅう》が少《すく》ない家《いえ》の学生《がくせい》など。授業料《じゅぎょうりょう》などをへらすことをみとめる、確認《かくにん》大学《だいがく》等《とう》をつくった人《ひと》。そして国《くに》です。",
  "hs": "3人以上の子どもなどの生計を維持《いじ》する人に生計を維持《いじ》されている学生など（多子世帯の学生など、所得制限なし）、低所得者世帯の学生など、授業料等の減免《げんめん》の認定を行う確認大学等の設置者、国。"
 },
 "more/committee/text": {
  "es": "3月《がつ》13日《にち》に、衆議院《しゅうぎいん》の本会議《ほんかいぎ》で、この案《あん》の説明《せつめい》と質問《しつもん》がありました。そして、文部科学委員会《もんぶかがくいいんかい》で話《はな》し合《あ》うことになりました（付託《ふたく》）。委員会《いいんかい》は14日《か》に、あべ文部科学大臣《もんぶかがくだいじん》から説明《せつめい》を聞《き》き、質問《しつもん》を始《はじ》めました。18日《にち》と19日《にち》にも質問《しつもん》をしました。質問《しつもん》が終《お》わったあと、立憲民主党《りっけんみんしゅとう》・無所属《むしょぞく》と国民民主党《こくみんみんしゅとう》・無所属《むしょぞく》クラブが、いっしょに直《なお》す案《あん》（修正案《しゅうせいあん》）を出《だ》しました。修正案《しゅうせいあん》は賛成《さんせい》が少《すく》なく、通《とお》りませんでした。もとの案《あん》は賛成《さんせい》が多《おお》く、そのまま通《とお》すべきものとされました。委員会《いいんかい》の注文《ちゅうもん》（附帯決議《ふたいけつぎ》）もつけられました。参議院《さんぎいん》の文教科学委員会《ぶんきょうかがくいいんかい》では、質問《しつもん》がありました。法律《ほうりつ》の目的《もくてき》を変《か》える理由《りゆう》や、ささえる人《ひと》をふやす必要《ひつよう》があるか、成績《せいせき》についての条件《じょうけん》のあり方《かた》などについてです。日本共産党《にほんきょうさんとう》とれいわ新選組《しんせんぐみ》が、反対《はんたい》の意見《いけん》を述《の》べました。採決《さいけつ》の結果《けっか》、賛成《さんせい》が多《おお》く、そのまま通《とお》すべきものとされました。ここでも附帯決議《ふたいけつぎ》がつけられました。",
  "hs": "3月13日に衆議院本会議で趣旨《しゅし》説明と質疑が行われ、文部科学委員会に付託《ふたく》された（審査《しんさ》を任された）。委員会は14日にあべ文部科学大臣から趣旨《しゅし》説明を聞いて質疑に入り、18日・19日にも質疑を行った。質疑の終了《しゅうりょう》後、立憲民主党・無所属と国民民主党・無所属クラブの共同提案の修正案が出されたが、賛成少数で否決され、本案は賛成多数で原案のとおり可決すべきものとされた。附帯決議《ふたいけつぎ》（委員会がつけた注文）がつけられた。参議院文教科学委員会では、法律の目的を改正する理由、支援《しえん》対象者を広げる必要性、学業の成績要件のあり方などについて質疑があった。日本共産党とれいわ新選組が反対の意見を述べ、採決の結果、多数で原案どおり可決すべきものとされた。附帯決議《ふたいけつぎ》がつけられた。"
 },
 "more/views/0/text": {
  "es": "日本維新《にっぽんいしん》の会《かい》は、必要《ひつよう》な改革《かいかく》を行《おこな》ったうえで、授業料《じゅぎょうりょう》などをなくすこと（無償化《むしょうか》）を行《おこな》うことを条件《じょうけん》に、賛成《さんせい》しました。国《くに》の会議《かいぎ》（中央教育審議会《ちゅうおうきょういくしんぎかい》）の意見《いけん》のまとめ（答申《とうしん》）の向《む》きが、党《とう》がめざす大学《だいがく》の改革《かいかく》とだいたい同《おな》じだったことを理由《りゆう》にあげました。党《とう》が必要《ひつよう》と考《かんが》える大学《だいがく》の改革《かいかく》の点《てん》が、すべて附帯決議《ふたいけつぎ》に書《か》かれたことなども理由《りゆう》にあげました。",
  "hs": "日本維新《にっぽんいしん》の会は、必要な改革を実行したうえでの無償化《むしょうか》の実現を条件に賛成した。中央教育審議会《ちゅうおうきょういくしんぎかい》の答申の方向性が党の目指す大学改革とおおよそ一致《いっち》したこと、党が必要と考える大学改革の論点がすべて附帯決議《ふたいけつぎ》に記載《きさい》されたことなどを理由に挙げた。"
 },
 "more/views/1/text": {
  "es": "れいわ新選組《しんせんぐみ》は、反対《はんたい》しました。子《こ》どもが多《おお》い家《いえ》（多子《たし》世帯《せたい》）の決《き》め方《かた》などのため、学生《がくせい》の9人《にん》のうち7人《にん》は、高《たか》くなる授業料《じゅぎょうりょう》をはらいつづけることになると述《の》べました。学《まな》ぶことをささえるお金《かね》を、消費税《しょうひぜい》でえたお金《かね》だけにしていることも理由《りゆう》にあげました。一番《いちばん》上《うえ》の子《こ》が卒業《そつぎょう》すると、2番目《ばんめ》の子《こ》がささえから外《はず》れるしくみであることも理由《りゆう》にあげました。",
  "hs": "れいわ新選組は、多子世帯の定義などにより、学生の9人のうち7人は高まる授業料を払《はら》い続けることになるとした。修学｜支援《しえん》の財源を消費税収に限っていること、第一子が卒業すると第二子が支援《しえん》から外れる制度設計であることも挙げて反対した。"
 }
}
